// ExportParts streams GET /api/v1/parts/export as CSV into writer (D35) and answers the
// rows it wrote; a cut export fails (D60).
func (c *Client) ExportParts(ctx context.Context, parameters PartsExportQuery, writer io.Writer) (int, error) {
	wire, err := parameters.wire()
	if err != nil {
		return 0, err
	}
	return c.runtime.Export(ctx, "/parts/export", wire, writer)
}
